using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.Build.Reporting;using UnityEngine;
public static class WindowsAlphaBuild {
 const string Version="0.1.0-alpha.1";
 [Serializable] class Record {public string version,sourceCommit,unityVersion,result,outputPath,target,backend,options;public ulong totalSize;public double seconds;public int errors,warnings;}
 static string Arg(string name,string fallback){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,name);return i>=0&&i+1<a.Length?a[i+1]:fallback;}
 [MenuItem("Release/Build Windows Alpha")]public static void Run(){try{var root=Directory.GetParent(Application.dataPath).FullName;var output=Path.GetFullPath(Arg("-releaseOutput",Path.Combine(root,"Builds/Windows/"+Version)));var records=Path.GetFullPath(Arg("-releaseRecordDir",Path.Combine(root,"BuildRecords/"+Version)));if(Directory.Exists(output)&&Directory.EnumerateFileSystemEntries(output).Any())throw new Exception("Release output must be empty: "+output);if(Application.unityVersion!="6000.3.19f1"||PlayerSettings.bundleVersion!=Version||PlayerSettings.productName!="ImmuneDefense2D")throw new Exception("Unexpected Unity/version/product settings");Directory.CreateDirectory(output);Directory.CreateDirectory(records);EditorUserBuildSettings.development=false;EditorUserBuildSettings.allowDebugging=false;EditorUserBuildSettings.connectProfiler=false;var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/Scenes/Level01.unity"},locationPathName=Path.Combine(output,"ImmuneDefense2D.exe"),target=BuildTarget.StandaloneWindows64,options=BuildOptions.None});var s=report.summary;var record=new Record{version=Version,sourceCommit=Arg("-sourceCommit","not supplied (menu build)"),unityVersion=Application.unityVersion,result=s.result.ToString(),outputPath=s.outputPath,target=s.platform.ToString(),backend=PlayerSettings.GetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Standalone).ToString(),options=s.options.ToString(),totalSize=s.totalSize,seconds=s.totalTime.TotalSeconds,errors=s.totalErrors,warnings=s.totalWarnings};File.WriteAllText(Path.Combine(records,"build-report.json"),JsonUtility.ToJson(record,true));if(s.result!=BuildResult.Succeeded)throw new Exception("Build failed; see BuildReport");foreach(var f in new[]{"README.txt","RELEASE_NOTES.md"})File.Copy(Path.Combine(root,"Documentation/Release/"+Version,f),Path.Combine(output,f));var licenses=Path.Combine(output,"Licenses");Directory.CreateDirectory(licenses);File.Copy(Path.Combine(root,"Assets/Fonts/LICENSE"),Path.Combine(licenses,"Noto-OFL-LICENSE.txt"));File.Copy(Path.Combine(root,"Assets/TextMesh Pro/Fonts/LiberationSans - OFL.txt"),Path.Combine(licenses,"LiberationSans-OFL.txt"));var cache=Path.Combine(root,"Library/PackageCache");if(Directory.Exists(cache))foreach(var package in Directory.GetDirectories(cache)){var license=Directory.GetFiles(package,"*",SearchOption.TopDirectoryOnly).FirstOrDefault(f=>Path.GetFileName(f).StartsWith("LICENSE",StringComparison.OrdinalIgnoreCase));if(license!=null)File.Copy(license,Path.Combine(licenses,Path.GetFileName(package)+"-LICENSE.txt"));}Debug.Log("WINDOWS_ALPHA_BUILD_SUCCEEDED");if(Application.isBatchMode)EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);if(Application.isBatchMode)EditorApplication.Exit(1);else throw;}}
}
